'use strict';
// Living region: a small persistent society authored once per new game and owned by the engine afterwards.
// ON by default (worldFlags LIVING_REGION); disable with HOLODEK_LIVING_REGION=0.
// What is real (engine state): a gameplay plan fixed by the engine before any model call (each resident's obstacle and
// consequence); staged authoring with structural checks, one review against the permitted effects and one targeted
// repair; routes built from actual exits by the normal topology pass; residents generated by the normal population
// pipeline in reserved slots; each goal item either sealed in a hidden chamber (secretDoors) or released by an existing,
// built physical mechanism (puzzleMechanism + installed geometry), each in a different room away from its recipient;
// the request offered only after that placement exists, through the favor system's own mission records and commands
// and verified by its receipt; a physical fixture change in saved room geometry; a real exit opened; one successor
// request per completion, caused by the committed change and verified by the engine's give-item receipt.
// What is narrative-only: "standing", need pressure, and traveler movement, which only changes where a resident who has
// NOT been encountered yet will appear; it never relocates an already generated resident. Relationships and history are
// authored after the region is playable and are context only.
// One authoritative record per task: a regional quest stores the mission ID (or the delivery goal) and, once consumed,
// the receipt. Its status and the goal's status are derived from those records (questStatus, goalStatus), never stored.
const Ledger = require('./livingRegionLedger');
const Authoring = require('./livingRegionAuthoring');
const Topology = require('./livingRegionTopology');
const Fixture = require('./livingRegionFixture');
const World = require('./livingWorld');
const Plans = require('./residentPlans');
// The game's region: three communities with two residents each. Tests may narrow it to one community.
const CONFIG = { scope: { communities: 3, residentsPerCommunity: 2, factsMin: 3, factsMax: 8 } };
const SOURCE = 'engine-living-region-v2';
const VERSION = 5;
const RETRY_INTENT = /^\s*(?:please\s+)?(?:retry|regenerate|try again(?: to author)?|author)\b[^\n]*\bliving region\b/i;
const INTERNAL_NOTICE = /^(?:Living region\b|Route confirmed:|.+ wants .+\. The engine has not placed it yet)/;
const playerNotices = notices => notices.filter(notice => !INTERNAL_NOTICE.test(String(notice))).join('\n');
const I = () => require('../assets/dungeonInhabitants');
const lower = s => String(s ?? '').trim().toLowerCase();
const dbOf = state => { try { return JSON.parse(state.getRoomNameDatabase() || '{}'); } catch { return {}; } };
const field = (text, label) => String(text || '').match(new RegExp(`^${label}:[ \\t]*([^\\r\\n]*)`, 'm'))?.[1]?.trim() || '';
const turnOf = text => Number(field(text, 'Turns')) || 0;
function hash(s) { let h = 2166136261; for (const ch of String(s)) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); } return h >>> 0; }
function enabled() { try { return require('./worldFlags').on('LIVING_REGION'); } catch { return false; } }
function rootOf(db) { return db instanceof Map ? db.get('0,0,0') : db?.['0,0,0']; }
function regionOf(db) { const r = rootOf(db)?.livingRegion; return r?.source === SOURCE ? r : null; }
function homebrewWorld(db) { const s = rootOf(db)?.setting; return s?.kind === 'homebrew' ? s : null; }
const xyz = key => { const [x, y, z] = String(key).split(',').map(Number); return { x, y, z }; };
const P = () => require('../assets/physicalPuzzles');
// Background authoring jobs (relationship/history detail and successor intentions). They never block a turn: ensure
// starts them, turn merges finished results. Keyed by run; a restart simply starts the job again.
const JOBS = new Map(), AGENTS = new Map();
function kick(id, work) {
  if (JOBS.has(id)) return JOBS.get(id);
  const job = { id, done: false, value: null, startedAt: Date.now() };
  job.promise = Promise.resolve().then(work).then(v => v, e => ({ ok: false, reason: String(e?.message || e) })).then(v => { job.value = v; job.done = true; job.ms = Date.now() - job.startedAt; });
  JOBS.set(id, job); return job;
}
function take(id) { const job = JOBS.get(id); if (!job?.done) return null; JOBS.delete(id); return job; }
const jobs = { settle: () => Promise.all([...JOBS.values()].map(j => j.promise)), pending: () => [...JOBS.values()].filter(j => !j.done).map(j => j.id), clear: () => { JOBS.clear(); AGENTS.clear(); } };
function cotgSetting() { try { return String(require('./graveMasterStoryPrompts').settingOnce({}) || '').replace(/\s+/g, ' ').trim(); } catch { return ''; } }

// ---------- Authoring ----------
function context(state, consoleText = state.getUpdatedGameConsole?.() || '') {
  const db = dbOf(state), In = I();
  const pcs = In.parseSheets(consoleText, 'PC').map(a => a.name), companions = In.parseSheets(consoleText, 'NPCs in Party').map(a => a.name);
  const existing = new Set(Object.values(db).flatMap(r => [r?.name, ...Object.keys(r?.inhabitants?.actors || {}), ...(r?.regionalSite?.actors || []).map(a => a.name)]).filter(Boolean));
  const world = homebrewWorld(db) || (() => { try { return require('./settingLayer').current(); } catch { return null; } })();
  const setting = world ? { kind: 'original-world', name: world.name || null, genres: world.genres || [], premise: String(world.arc || world.history || world.realm || '') } :
    { kind: 'children-of-the-grave', premise: cotgSetting() || 'The established underworld campaign.' };
  return { runId: state.getDungeonRunId?.(), party: [...pcs, ...companions], companions, existingNames: [...existing], setting, homebrew: !!homebrewWorld(db) };
}
// A goal is the engine plan for one resident's request: the object, the obstacle that keeps it, the consequence the
// engine commits, and the authored reason. The goal text is composed from those fields.
function makeGoal(resident, g) {
  const kind = Authoring.GOAL_KIND[g.obstacle];
  return { id: g.id, kind, item: g.item, whyHidden: g.whyHidden, effect: g.effect, itemUse: g.itemUse, meaning: g.meaning || null,
    text: `Bring ${g.item} to ${resident.name} so they can ${g.itemUse}.`, publicized: false, consequence: Authoring.EFFECTS[g.effect],
    requiredKinds: Authoring.GOAL_TASKS[kind], requirements: { kind: 'retrieve', item: g.item, recipientId: resident.id },
    objective: { obstacle: g.obstacle, status: 'unplaced', tried: [] }, channel: g.channel || 'favor', ...(g.causedBy ? { causedBy: g.causedBy } : {}) };
}
function compile(accepted, ctx, { now = Date.now() } = {}) {
  const communities = accepted.communities.map((c, i) => ({ id: c.id, index: i, name: c.name, need: c.need, setting: c.setting,
    purpose: c.purpose || null, damage: c.damage || null, improvement: c.improvement || null, passageMatters: c.passageMatters || null, dangerMatters: c.dangerMatters || null,
    fixture: { id: 'lrfix:' + c.id, name: c.fixtureName, form: c.fixtureForm, state: 'damaged', history: [] },
    disagreement: c.disagreementWith ? { withId: c.disagreementWith, issue: c.disagreement } : null,
    pressure: 1, standing: 0, anchor: { key: null, status: 'unplanned' } }));
  const residents = accepted.residents.map(r => {
    const resident = { id: r.id, name: r.name, communityId: r.community, homeCommunityId: r.community, history: r.history, meaning: r.meaning || null,
      relationships: [], willingTraveler: r.willingTraveler, materialized: null, travels: [], pastGoals: [] };
    resident.goal = makeGoal(resident, { id: 'lrg:' + r.id, obstacle: r.obstacle || 'hidden-chamber', effect: r.effect, item: r.goalItem, whyHidden: r.whyHidden, itemUse: r.itemUse, meaning: r.meaning });
    return resident;
  });
  const region = { version: VERSION, source: SOURCE, runId: ctx.runId, createdAt: now, setting: ctx.setting.kind, plan: accepted.plan || null, review: accepted.reviewed || null,
    communities, residents, companionThreads: [], quests: [], routes: [], ledger: Ledger.create(ctx.runId), successors: [],
    social: { status: 'pending', tries: 0 },
    state: { moments: 0, lastCommunityId: null, developments: [], seenStays: [], unbound: {}, stranded: {}, told: [], mirrored: { facts: 0, beliefs: 0, threads: 0 }, notices: [] },
    // Deferred layers keep their data slots so they can be added without migrating saves.
    deferred: { rumorSpread: { enabled: false, channels: [] }, companionRivalry: { enabled: false }, factionShifts: { enabled: false, steps: [] } } };
  if (accepted.facts) applySocial(region, accepted, { now });
  return region;
}
// Relationships, history and companion stakes: context only, merged after the region is playable.
function applySocial(region, social, { now = Date.now() } = {}) {
  const nameOf = id => region.residents.find(r => r.id === id)?.name || id;
  for (const r of region.residents) r.relationships = (social.relationships || []).filter(x => x.from === r.id).map(x => ({ kind: x.kind, target: x.to, source: 'authored' }));
  (social.facts || []).forEach((f, i) => {
    const fact = Ledger.append(region.ledger, { kind: 'history', writer: 'authored-history', text: f.text, key: 'authored:' + i, communityId: f.community, actors: f.involves.map(nameOf), at: now, turn: 0 });
    if (fact) for (const b of f.beliefs) Ledger.believe(region.ledger, { factId: fact.id, holder: nameOf(b.holder), account: b.account, channel: 'authored', at: now });
  });
  region.companionThreads = (social.companionHooks || []).map((h, i) => ({ id: 'lrt:' + i, companion: h.companion, kind: h.kind, stake: h.stake, communityId: h.community, status: 'open' }));
  region.social = { ...(region.social || {}), status: 'authored', at: now };
}
function failureNotice(attempt) {
  return `Living region unavailable: this game's living region could not be authored (${attempt.reason || 'invalid answer'}). ` +
    `Accepted parts are kept${attempt.acceptedStages?.length ? ' (' + attempt.acceptedStages.join(', ') + ')' : ''}. Exploration, quests and favors continue normally. Type "retry living region" to try again.`;
}
// Called once per player turn after campaign planning. Authors the playable region only for a new game; a loaded save
// keeps its region. A failed attempt is reported and waits for an explicit retry, which resumes from accepted stages.
// Social detail and successor intentions are started here in the background and merged by turn().
async function ensure($, state, { userInput = '', consoleText = state.getUpdatedGameConsole?.() || '', request, scope, timing = null } = {}) {
  if (!enabled()) return { status: 'disabled' };
  const runId = state.getDungeonRunId?.(); if (!runId) return { status: 'no-run' };
  AGENTS.set(runId, { $, request });
  let db = dbOf(state); db['0,0,0'] ||= {};
  if (db['0,0,0'].livingRegion?.runId === runId) {
    const region = regionOf(db);
    if (region) {
      if (RETRY_INTENT.test(String(userInput || ''))) {
        if (region.social?.status === 'failed') region.social = { status: 'pending', tries: 0 };
        for (const s of (region.successors || []).filter(s => s.status === 'failed')) Object.assign(s, { status: 'queued', tries: 0 });
        persist(state, region);
      }
      // A job lost with the process (status running, no job in memory) is started again.
      if (region.social?.status === 'running' && !JOBS.has(`${runId}:social`)) region.social.status = 'pending';
      for (const s of (region.successors || []).filter(s => s.status === 'running' && !JOBS.has(`${runId}:successor:${s.id}`))) s.status = 'queued';
      if(Object.keys(region.world?.planAttempts||{}).length){const recovered=dbOf(state);let changed=false;
        for(const entry of PlansIndex(recovered))if(entry.request.status==='running'&&!JOBS.has(entry.request.id)){entry.request.status='queued';changed=true;}
        if(changed){recovered['0,0,0'].livingRegion=region;state.setRoomNameDatabase(JSON.stringify(recovered));}}
      startJobs(state, region, consoleText);
    }
    return { status: 'present' };
  }
  const attempt = db['0,0,0'].livingRegionAttempt?.runId === runId ? db['0,0,0'].livingRegionAttempt : null;
  const retry = attempt?.status === 'failed' && RETRY_INTENT.test(String(userInput || ''));
  if (attempt && !retry) return { status: attempt.status };
  if (!attempt && turnOf(consoleText) > 1) {
    db['0,0,0'].livingRegionAttempt = { runId, status: 'skipped', reason: 'This saved campaign predates living regions.', at: Date.now(), source: SOURCE };
    state.setRoomNameDatabase(JSON.stringify(db));
    return { status: 'skipped' };
  }
  db['0,0,0'].livingRegionAttempt = { ...(attempt || {}), runId, status: 'running', tries: (attempt?.tries || 0) + 1, at: Date.now(), source: SOURCE };
  state.setRoomNameDatabase(JSON.stringify(db));
  const ctx = context(state, consoleText);
  console.info('[LivingRegion]', JSON.stringify({ runId, phase: 'authoring', retry, resume: Object.keys(attempt?.accepted || {}) }));
  const result = await Authoring.author($, ctx, { ...(request ? { request } : {}), accepted: attempt?.accepted || {}, scope: scope || CONFIG.scope, timing });
  if (state.getDungeonRunId?.() !== runId) return { status: 'stale' };
  db = dbOf(state); db['0,0,0'] ||= {};
  const record = db['0,0,0'].livingRegionAttempt?.runId === runId ? db['0,0,0'].livingRegionAttempt : { runId, tries: 1, source: SOURCE };
  if (result.ok) {
    const region = compile(result.accepted, ctx);
    region.scope = scope || CONFIG.scope; World.init(region).cost.modelCalls.authoring = (result.trace || []).length;
    // The playable footprint is reserved and saved here, before any helper can be dispatched next to it.
    const footprint = reserveFootprint(db, region, state);
    const status = footprint.ok ? 'generated' : 'footprint-blocked';
    db['0,0,0'].livingRegion = region;
    db['0,0,0'].livingRegionAttempt = { runId, status, tries: record.tries, trace: result.trace, at: Date.now(), source: SOURCE, ...(footprint.ok ? {} : { blocked: footprint.blocked }) };
    state.setRoomNameDatabase(JSON.stringify(db));
    mirror(state, region); persist(state, region);
    startJobs(state, region, consoleText, ctx);
    console.info('[LivingRegion]', JSON.stringify({ runId, phase: status, communities: region.communities.map(c => c.name), residents: region.residents.length, review: region.review,
      footprint: region.routes.map(r => ({ community: r.communityId, rooms: r.footprint?.rooms, extension: r.extension || null })) }));
    return { status, region };
  }
  const acceptedStages = ['communities', 'residents'].filter(k => result.accepted?.[k]);
  db['0,0,0'].livingRegionAttempt = { runId, status: 'failed', tries: record.tries, reason: result.reason, failedStage: result.stage, accepted: result.accepted,
    acceptedStages, trace: result.trace, noticePending: true, at: Date.now(), source: SOURCE };
  state.setRoomNameDatabase(JSON.stringify(db));
  console.warn('[LivingRegion] FAILED', JSON.stringify({ runId, stage: result.stage, reason: result.reason, kept: acceptedStages, retry: 'Type "retry living region".' }));
  return { status: 'failed', reason: result.reason, stage: result.stage };
}
// Starts the background jobs this region is waiting for (needs the agent from the latest ensure call).
function startJobs(state, region, consoleText = state.getUpdatedGameConsole?.() || '', ctx = null) {
  const agent = AGENTS.get(region.runId); if (!agent) return [];
  const started = [], opts = agent.request ? { request: agent.request } : {};
  if (region.social?.status === 'pending') {
    const c = ctx || context(state, consoleText), accepted = acceptedOf(region);
    started.push(kick(`${region.runId}:social`, () => Authoring.authorSocial(agent.$, c, accepted, { ...opts, scope: region.scope || CONFIG.scope })).id); World.count(region, 'social');
    region.social.status = 'running'; region.social.startedAt = Date.now(); persist(state, region);
  }
  for (const s of region.successors.filter(s => s.status === 'queued')) {
    const c = ctx || context(state, consoleText);
    started.push(kick(`${region.runId}:successor:${s.id}`, () => Authoring.authorSuccessor(agent.$, c, s.input, opts)).id); World.count(region, 'successor');
    s.status = 'running'; s.startedAt = Date.now(); persist(state, region);
  }
  // A character who became important in play takes on a regional request (one call, at most one at a time).
  for (const a of (region.world?.adoptions || []).filter(a => a.status === 'queued').slice(0, 1)) {
    if ((region.world.adoptions || []).some(x => x.status === 'running')) break;
    const c = ctx || context(state, consoleText);
    started.push(kick(`${region.runId}:adopt:${a.id}`, () => Authoring.authorSuccessor(agent.$, c, a.input, opts)).id); World.count(region, 'adoption');
    a.status = 'running'; a.startedAt = Date.now(); persist(state, region);
  }
  if(Object.keys(region.world?.planAttempts||{}).length){const db=dbOf(state),pending=PlansIndex(db);
  if(!pending.some(p=>p.request.status==='running'))for(const entry of pending.filter(p=>p.request.status==='queued').slice(0,1)){
    const request=structuredClone(entry.request),c={...(ctx||context(state,consoleText)),
      history:region.world.people?.[lower(entry.name)],knowledge:World.knownBy(region,[entry.name],{limit:6}).map(f=>({id:f.id,text:f.text}))};
    started.push(kick(request.id,()=>Plans.author(agent.$,c,entry,request,agent.request)).id);World.count(region,'resident-plan');
    entry.request.status='running';Plans.publish(state,db,new Set([entry.roomKey]),I().roomKey(field(consoleText,'Coordinates')));
    db['0,0,0'].livingRegion=region;state.setRoomNameDatabase(JSON.stringify(db));
  }}
  return started;
}
function PlansIndex(db){return [...World.index(db).where.values()].filter(e=>e.record.residentPlanRequest?.source===Plans.SOURCE)
  .map(e=>({...e,request:e.record.residentPlanRequest}));}
// The accepted plan, as authoring stages see it (for the deferred social stage).
function acceptedOf(region) {
  return { plan: region.plan, communities: region.communities.map(c => ({ id: c.id, name: c.name, setting: c.setting, fixtureName: c.fixture.name, fixtureForm: c.fixture.form,
      purpose: c.purpose, damage: c.damage, need: c.need, improvement: c.improvement })),
    residents: region.residents.map(r => ({ id: r.id, name: r.name, community: r.homeCommunityId, goalItem: r.goal.item, obstacle: r.goal.objective.obstacle, effect: r.goal.effect, itemUse: r.goal.itemUse, history: r.history })) };
}
// Finished background results are merged on the next turn. One retry each; then a visible notice with a retry offer.
function mergeJobs(db, region, state, notices, touched = new Set()) {
  for(const entry of PlansIndex(db).filter(e=>e.request.status==='running')){
    const job=take(entry.request.id);if(!job)continue;
    if(job.value?.choice){Plans.install(entry.record,entry.request,job.value,turnOf(state.getUpdatedGameConsole?.()||''));}
    else if(entry.request.attempt<2){entry.request.attempt++;entry.request.status='queued';}
    else{entry.request.status='failed';entry.request.reason=job.value?.reason||'No accepted plan.';World.guard(region,'resident-plan-failed',entry.name,entry.request.reason);}
    touched.add(entry.roomKey);
  }
  const social = take(`${region.runId}:social`);
  if (social && region.social?.status === 'running') {
    if (social.value?.ok) { applySocial(region, social.value.accepted); region.social.ms = social.ms; console.info('[LivingRegion]', JSON.stringify({ phase: 'social-authored', ms: social.ms, facts: region.ledger.facts.length })); }
    else {
      region.social.tries = (region.social.tries || 0) + 1; region.social.reason = social.value?.reason || 'invalid answer';
      if (region.social.tries < 2) region.social.status = 'pending';
      else { region.social.status = 'failed';
        notices.push(`Living region detail unavailable: relationships and history could not be authored (${region.social.reason}). The communities, requests and consequences are unaffected. Type "retry living region" to try again.`); }
      console.warn('[LivingRegion]', JSON.stringify({ phase: 'social-failed', tries: region.social.tries, reason: region.social.reason }));
    }
  }
  for (const s of region.successors.filter(s => s.status === 'running')) {
    const job = take(`${region.runId}:successor:${s.id}`); if (!job) continue;
    const resident = region.residents.find(r => r.id === s.residentId);
    if (job.value?.ok && resident && !ended(resident.goal)) {
      resident.pastGoals.push(resident.goal);
      resident.goal = makeGoal(resident, { id: s.goalId, obstacle: s.input.slot.obstacle, effect: s.input.slot.effect, item: job.value.goal.goalItem, whyHidden: job.value.goal.whyHidden,
        itemUse: job.value.goal.itemUse, meaning: job.value.goal.meaning, channel: 'delivery', causedBy: s.causedBy });
      Object.assign(s, { status: 'authored', ms: job.ms, at: Date.now() });
      retag(db, state, region, resident); if (resident.materialized?.roomKey) touched.add(resident.materialized.roomKey);
      fact(region, { kind: 'development', writer: 'development', key: 'successor:' + s.goalId, text: `Because ${s.causedBy.change}, ${resident.name} now wants: ${resident.goal.text}`,
        communityId: resident.homeCommunityId, actors: [resident.name], evidence: [{ missionId: s.causedBy.missionId, receipt: s.causedBy.receipt }], turn: 0,
        notice: `Regional development: because ${s.causedBy.change}, ${resident.name} has a new aim: ${resident.goal.text} You will be told where ${resident.goal.item} is once the engine has placed it.` }, notices);
      console.info('[LivingRegion]', JSON.stringify({ phase: 'successor-authored', goalId: s.goalId, resident: resident.name, obstacle: s.input.slot.obstacle, effect: s.input.slot.effect, ms: job.ms }));
    } else {
      s.tries = (s.tries || 0) + 1; s.reason = job.value?.reason || 'invalid answer';
      if (s.tries < 2) s.status = 'queued';
      else { s.status = 'failed'; notices.push(`Living region: ${resident?.name || 'a resident'}'s next request could not be authored (${s.reason}). Nothing else changed. Type "retry living region" to try again.`); }
    }
  }
}
// An adopted character keeps their own identity and record; only a regional role and one request are added.
function mergeAdoptions(db, region, state, notices, touched) {
  for (const a of (region.world?.adoptions || []).filter(a => a.status === 'running')) {
    const job = take(`${region.runId}:adopt:${a.id}`); if (!job) continue;
    const record = db[a.roomKey]?.inhabitants?.actors?.[a.name];
    if (!job.value?.ok || !record || record.status === 'dead' || record.status === 'recruited') {
      a.tries = (a.tries || 0) + 1; a.reason = job.value?.reason || (!record ? 'the character is no longer recorded there' : 'invalid answer');
      a.status = a.tries < 2 && record ? 'queued' : 'failed';
      if (a.status === 'failed') notices.push(`Living region: ${a.name}'s own request could not be authored (${a.reason}). Nothing else changed.`);
      continue;
    }
    const g = job.value.goal, resident = { id: a.id, name: a.name, communityId: a.communityId, homeCommunityId: a.communityId, history: a.input.resident.history, meaning: g.meaning,
      relationships: [], willingTraveler: false, materialized: { roomKey: a.roomKey, at: Date.now() }, travels: [], pastGoals: [], adopted: true };
    resident.goal = makeGoal(resident, { id: `lrg:${a.id}`, obstacle: 'mechanism', effect: 'earn-trust', item: g.goalItem, whyHidden: g.whyHidden, itemUse: g.itemUse, meaning: g.meaning,
      channel: 'delivery', causedBy: { adoption: a.id, change: `${a.name} has dealt with the party before` } });
    region.residents.push(resident);
    record.livingRegion = { source: SOURCE, runId: region.runId, residentId: resident.id, goalId: resident.goal.id, adopted: true };
    const live = state.getRoomPopulation?.(a.roomKey);
    if (live?.actors?.[a.name] && live !== db[a.roomKey].inhabitants) { live.actors[a.name].livingRegion = { ...record.livingRegion }; state.setRoomPopulation?.(a.roomKey, live); }
    touched.add(a.roomKey);
    Object.assign(a, { status: 'adopted', residentId: resident.id, ms: job.ms, at: Date.now() });
    fact(region, { kind: 'development', writer: 'development', key: 'adopted:' + a.id, text: `${a.name} now has an aim of their own in the region: ${resident.goal.text}`, communityId: a.communityId, roomKey: a.roomKey,
      actors: [a.name], turn: 0, notice: `Regional development: ${a.name} has an aim of their own (${resident.goal.text}). You will be told where ${resident.goal.item} is once the engine has placed it.` }, notices);
    console.info('[LivingRegion]', JSON.stringify({ phase: 'adopted', name: a.name, residentId: resident.id, goalId: resident.goal.id, ms: job.ms }));
  }
}
// The generated record's tag follows the resident's current goal.
function retag(db, state, region, resident) {
  const key = resident.materialized?.roomKey; if (!key) return;
  const record = db[key]?.inhabitants?.actors?.[resident.name];
  if (record?.livingRegion) record.livingRegion.goalId = resident.goal.id;
  const live = state.getRoomPopulation?.(key);
  if (live?.actors?.[resident.name]?.livingRegion && live !== db[key]?.inhabitants) { live.actors[resident.name].livingRegion.goalId = resident.goal.id; state.setRoomPopulation?.(key, live); }
}
